function safeError(error:unknown){
 const message=error instanceof Error?error.message:"";
 if(/access denied|forbidden|merchant access/i.test(message)) return "Merchant access is required.";
 const safe=[
  ["Fresh authentication required","Please sign in again before changing security-sensitive settings."],
  ["Bearer token is required","A bearer token is required for this authentication mode."],
  ["API key is required","An API key is required for this authentication mode."],
  ["Basic username and password are required","A username and password are required for this authentication mode."],
  ["Enterprise catalog webhook secret is required when enabling webhooks","A webhook secret is required before enabling catalog webhooks."],
  ["Enterprise catalog webhook secret must be at least 32 characters","Webhook secrets must contain at least 32 characters."],
  ["Enterprise order webhook secret must be at least 32 characters","Order webhook secrets must contain at least 32 characters."],
  ["Endpoint must use HTTPS","Enterprise endpoints must use HTTPS."],
  ["Endpoint targets a private or reserved network","That enterprise endpoint is not allowed."],
  ["Endpoint resolves to a private or reserved network","That enterprise endpoint is not allowed."],
  ["Non-standard HTTPS ports are not allowed","Enterprise endpoints must use standard HTTPS."],
  ["Enterprise catalog endpoint no longer resolves to a public address","The enterprise endpoint is currently unreachable."],
  ["Enterprise connection is not configured","Configure the enterprise connection first."],
  ["Enterprise catalog connection test failed","The enterprise connection test failed."],
  ["verified active user not found","Use the email address of an active ELEMARKET account with verified email."],
  ["location-scoped role requires a location","Choose a location for this staff role."],
  ["cannot remove the last active enterprise administrator","Add another enterprise administrator before suspending or revoking this one."],
  ["enterprise organization access denied","Your enterprise role does not permit this operation."],
  ["enterprise location role access denied","Your enterprise role does not permit this location operation."],
 ];
 const hit=safe.find(([needle])=>message===needle || message.includes(needle));
 return hit?.[1] ?? "The operation could not be completed. Please try again.";
}
export const Route=createFileRoute("/merchant/dashboard")({loader:async()=>({dashboard:await loadMerchantDashboard(),taxonomy:await loadActiveCatalogTaxonomy()}),component:Dashboard,errorComponent:({error})=><main className="mx-auto max-w-xl px-4 py-16 text-center"><h1 className="text-3xl font-black">Merchant access required</h1><p className="mt-3 text-sm text-market-muted">{safeError(error)}</p></main>});
function money(v:string){const n=Number(v);return Number.isFinite(n)?n.toLocaleString("en-GH",{minimumFractionDigits:2,maximumFractionDigits:2}):v}
function date(v:string){const d=new Date(v);return Number.isNaN(d.getTime())?v:d.toLocaleString("en-GH",{dateStyle:"medium",timeStyle:"short"})}
const tabs=["Overview","Products","Inventory","Orders","Finance","Business","KYB","Promotions","Advertising","Enterprise","Locations"] as const;
type Tab=typeof tabs[number];
type FulfillmentType = "delivery" | "pickup" | "delivery_and_pickup";
type EnterpriseLocationType = "store" | "warehouse" | "distribution_center" | "fulfillment_center" | "pickup_point" | "office" | "service_center";
type MerchantDashboardData = Awaited<ReturnType<typeof loadMerchantDashboard>>;
type EnterpriseSyncRun = { id:string; status:string; source:string; generation:string|number; started_at:string; completed_at:string|null; received_count:number; upserted_count:number; deactivated_count:number; error_count:number; cursor_pages:number; error_code:string|null };
type EnterpriseWebhookEvent = { id:string; event_type:string; status:string; attempts:number; received_at:string; processed_at:string|null; next_attempt_at:string|null; error_code:string|null };
type EnterpriseOrderOutbox = { id:string; order_id:string; event_type:string; status:string; attempts:number; available_at:string|null; sent_at:string|null; error_code:string|null; created_at:string; updated_at:string };
type MerchantProduct = { id:string; name:string; category:string; subcategory:string|null; brand:string|null; model:string|null; sku:string|null; status:string; price:string; stock:number; listing_type:string; attributes:JsonObject; returnable:boolean; return_window_days:number|null; warranty_months:number|null; fulfillment_type:FulfillmentType; description?:string; created_at:string };
type MerchantOrder = { id:string; status:string; grand_total:string; product_total:string; delivery_total:string; address:string; created_at:string; updated_at:string; delivered_at:string|null; eligible_at:string|null; withdrawal_reason:string; withdrawal_eligible:boolean; dispute_filed_at:string|null };
type MerchantVariant = { id:string; product_id:string; sku:string; name:string|null; price:string; stock:number; status:string; attributes:JsonObject };
type MerchantFinance = { balance:{currency:string; totalSales:string; platformCommission:string; merchantOrderValue:string; refundExceptionAmount:string; providerHeldEligible:string; providerRequestable:string; pendingReleaseRequests:string; providerWithdrawalEligibility:{eligibleAmount:string|number;eligibleOrders:number;activeDisputes:number;currency:string;custodyBoundary:string;withdrawalAction:string}}; refundRequests:Array<{id:string;orderId:string;amount:string;status:string;reason:string;createdAt:string;resolvedAt:string|null}> };
type MerchantFinancingProviderRow={id:string;name:string;product_type:string;integration_mode:string;provider_legal_name:string|null;terms_url:string|null;privacy_url:string|null;minimum_application_amount:string|null;maximum_application_amount:string|null};
type MerchantFinancingApplicationRow={id:string;provider_id:string;provider_name:string;requested_amount:string;currency:string;status:string;score_snapshot:number|null;redirect_url:string|null;created_at:string};
type Merchant = { productMedia:Array<{id:string;product_id:string;alt_text:string|null;is_primary:boolean;url:string}>; merchant_id:string; name:string; category:string; catalog_categories:string[]; city:string; neighborhood:string; address:string; description:string; verified:boolean; tier:string; settlement_model:string; catalog_source:string; catalogSource:string; orders:number; profile:{name:string;description:string;category:string;categories:string[];address:string;city:string;neighborhood:string}; products:MerchantProduct[]; recentOrders:MerchantOrder[]; activities:Array<{id:string;type:"order"|"listing";title:string;detail:string;status:string;createdAt:string}>; variants:MerchantVariant[]; inventoryHistory:Array<{id:string;product_id:string;variant_id:string|null;delta:number;reason:string;actor_user_id:string;created_at:string}>; finance:MerchantFinance; merchantHealth:JsonObject|null; merchantFinancingProviders:MerchantFinancingProviderRow[]; merchantFinancingApplications:MerchantFinancingApplicationRow[]; performance:JsonObject|null; funnel:JsonObject|null; productQuestions:Array<{id:string;product_id:string;product_name:string;question:string;created_at:string}>; enterpriseCatalog:{status:string;endpoint_url:string;auth_type:string;response_path:string;sync_mode:string;last_sync_status:string|null;last_sync_completed_at:string|null;last_sync_count:number;webhook_enabled:boolean;page_size:number;cursor_param:string;cursor_path:string|null;inventory_stale_after_seconds:number;last_inventory_sync_at:string|null;last_connection_test_at:string|null;last_connection_test_status:string|null;last_connection_test_error:string|null;order_endpoint_url:string|null;order_webhook_enabled:boolean}|null;enterpriseHealth:EnterpriseHealth|null;enterpriseOps:{syncRuns:EnterpriseSyncRun[];webhookEvents:EnterpriseWebhookEvent[];orderOutbox:EnterpriseOrderOutbox[]}|null; kyb:{id:string;status:string;registration_number:string|null;business_name:string;business_type:string|null;tax_registration_status:string|null;vat_registration_status:string|null;settlement_method:string|null;check_status:string|null;created_at:string}|null; promotions:Array<{promotionId:string;name:string;status:string;startsAt:string;endsAt:string;participationRequired:boolean;participationStatus:string|null;termsVersion:string|null}> };
type RunAction=(fn:()=>Promise<unknown>,success:string)=>Promise<void>;
type ProductEditForm={attributes:JsonObject;name:string;category:string;subcategory:string;brand:string;model:string;sku:string;price:string;description:string;returnable:boolean;returnWindowDays:string;warrantyMonths:string;fulfillmentType:"delivery"|"pickup"|"delivery_and_pickup"};

function Button({children,...props}:ButtonHTMLAttributes<HTMLButtonElement>){return <button {...props} className={`rounded-xl px-4 py-2 text-sm font-black disabled:opacity-50 ${props.className??"bg-market-green text-white"}`}>{children}</button>}
function Dashboard(){
 const loaded=Route.useLoaderData() as {dashboard:MerchantDashboardData;taxonomy:ActiveCatalogGroup[]}; const d=loaded.dashboard; const taxonomy=loaded.taxonomy; const [merchantId,setMerchantId]=useState(d.merchants[0]?.merchant_id??""); const [tab,setTab]=useState<Tab>("Overview");
 const m=d.merchants.find(x=>x.merchant_id===merchantId)??d.merchants[0];
 const [message,setMessage]=useState<string|null>(null); const [busy,setBusy]=useState(false);
 if(!m)return <main className="mx-auto max-w-xl px-4 py-16 text-center"><h1 className="text-3xl font-black">No active merchant workspace</h1></main>;
 async function run(fn:()=>Promise<unknown>,success:string){setBusy(true);setMessage(null);try{await fn();setMessage(success);window.location.reload()}catch(e){setMessage(safeError(e))}finally{setBusy(false)}}
 return <main className="mx-auto max-w-7xl px-4 py-6 sm:px-6">
  <header className="rounded-3xl border border-market-line bg-white p-5 shadow-market sm:p-7"><div className="mb-5 flex flex-wrap items-center gap-2 text-xs font-bold"><a href={portalHref("marketplace")} className="text-market-green hover:underline">← Marketplace</a><span className="text-market-muted">/</span><span className="text-market-muted">Seller workspace</span></div><div className="flex flex-wrap items-start justify-between gap-4"><div><p className="text-xs font-black uppercase tracking-[.16em] text-market-muted">ELEMARKET Merchant Operations</p><h1 className="mt-2 text-3xl font-black">{m.name}</h1><p className="mt-1 text-sm text-market-muted">{(m.catalog_categories?.length?m.catalog_categories:[m.category]).join(" · ")} · {m.city} · {m.neighborhood}</p></div><div className="flex items-center gap-2">{d.merchants.length>1?<select value={merchantId} onChange={e=>{setMerchantId(e.target.value);setTab("Overview")}} className="h-10 rounded-xl border border-market-line px-3 text-sm font-bold">{d.merchants.map(x=><option key={x.merchant_id} value={x.merchant_id}>{x.name}</option>)}</select>:null}<span className="rounded-full bg-black px-3 py-2 text-xs font-bold text-white">{m.verified?"Verified merchant":"Active merchant"}</span></div></div>
  <nav role="tablist" aria-label="Merchant workspace sections" className="mt-6 flex gap-2 overflow-x-auto border-t border-market-line pt-4 pb-1">{tabs.map((t,index)=><button type="button" role="tab" id={`merchant-tab-${index}`} aria-controls="merchant-workspace-panel" aria-selected={tab===t} tabIndex={tab===t?0:-1} key={t} onClick={()=>setTab(t)} onKeyDown={event=>{if(!["ArrowRight","ArrowLeft","Home","End"].includes(event.key))return;event.preventDefault();const destination=event.key==="Home"?0:event.key==="End"?tabs.length-1:(index+(event.key==="ArrowRight"?1:-1)+tabs.length)%tabs.length;setTab(tabs[destination]);const buttons=event.currentTarget.parentElement?.querySelectorAll<HTMLButtonElement>('[role="tab"]');buttons?.[destination]?.focus();}} className={`min-h-11 whitespace-nowrap rounded-xl px-4 py-2 text-sm font-black transition ${tab===t?"bg-market-green text-white shadow-sm":"bg-market-soft text-market-ink hover:bg-market-line"}`}>{t}</button>)}</nav></header>
  {message?<div role="status" aria-live="polite" className="mt-4 rounded-xl border border-market-line bg-market-soft p-3 text-sm font-semibold">{message}</div>:null}
  <div key={m.merchant_id} id="merchant-workspace-panel" role="tabpanel" aria-labelledby={`merchant-tab-${tabs.indexOf(tab)}`} tabIndex={0} className="mt-6">{tab==="Overview"?<Overview m={m}/>:tab==="Products"?<Products m={m} run={run} busy={busy} taxonomy={taxonomy}/>:tab==="Inventory"?<Inventory m={m} run={run} busy={busy}/>:tab==="Orders"?<Orders m={m} run={run} busy={busy}/>:tab==="Finance"?<Finance m={m}/>:tab==="Business"?<Business m={m} run={run} busy={busy} taxonomy={taxonomy}/>:tab==="KYB"?<Kyb m={m}/>:tab==="Promotions"?<Promotions m={m} run={run} busy={busy}/>:tab==="Advertising"?<Advertising m={m}/>:tab==="Enterprise"?<Enterprise m={m} run={run} busy={busy}/>:<Locations merchantId={m.merchant_id}/>}</div>
  <ContactSupportWidget />
 </main>;
}
function Card({title,children,wide=false}:{title:string;children:ReactNode;wide?:boolean}){return <section className={`rounded-2xl border border-market-line bg-white p-5 shadow-market ${wide?"lg:col-span-2":""}`}><h2 className="text-xl font-black">{title}</h2>{children}</section>}
function Overview({m}:{m:Merchant}){
 const perf=m.performance??{}; const [answers,setAnswers]=useState<Record<string,string>>({}); const performanceMetrics: Array<[string, string | number]>=[["90-day orders",Number(perf.orders??0)],["Cancellation rate",`${perf.cancellationRate??0}%`],["Verified reviews",Number(perf.reviewCount??0)],["Average rating",Number(perf.reviewCount??0)>0?`${Number(perf.avgRating??0).toFixed(1)}/5`:"No reviews"]];
 async function answer(q:{id:string}){const value=(answers[q.id]??"").trim(); if(value.length<2)return; await answerProductQuestion({data:{merchantId:m.merchant_id,questionId:q.id,answer:value}}); window.location.reload();}
 return <div className="grid gap-5 lg:grid-cols-2"><Card title="Sales & commission"><p className="sr-only">Product sales · ELEMARKET commission · Merchant order value</p><div className="mt-4 grid grid-cols-2 gap-3 sm:grid-cols-4">{[["Listings",m.products.length],["Orders",m.orders],["Sales",`GHS ${money(m.finance.balance.totalSales)}`],["Commission",`GHS ${money(m.finance.balance.platformCommission)}`]].map(([a,b])=><div key={String(a)} className="rounded-xl border border-market-line p-4"><p className="text-xs font-bold text-market-muted">{a}</p><p className="mt-2 text-2xl font-black">{b}</p></div>)}</div></Card><Card title="Merchant activities"><div className="mt-3 space-y-3">{m.activities.slice(0,10).map(x=><div key={x.id} className="flex justify-between gap-3 border-b border-market-line pb-3"><div><p className="font-bold">{x.title}</p><p className="text-xs text-market-muted">{x.detail}</p></div><div className="text-right text-xs font-bold"><p>{x.status}</p><p className="text-market-muted">{date(x.createdAt)}</p></div></div>)}</div></Card><Card title="Seller performance · last 90 days" wide><div className="grid gap-3 sm:grid-cols-4">{performanceMetrics.map(([label,value])=><div key={String(label)} className="rounded-xl border border-market-line p-4"><p className="text-xs font-bold text-market-muted">{label}</p><p className="mt-2 text-2xl font-black">{String(value)}</p></div>)}</div><p className="mt-4 text-xs leading-5 text-market-muted">These are operational facts from completed ELEMARKET orders and verified-purchase reviews—not a customer-facing seller score or financing decision.</p></Card><Card title="Customer questions" wide>{m.productQuestions.length===0?<p className="mt-3 text-sm text-market-muted">No unanswered product questions.</p>:<div className="mt-3 space-y-4">{m.productQuestions.map(q=><div key={q.id} className="rounded-xl border border-market-line p-4"><div className="flex flex-wrap items-start justify-between gap-2"><div><p className="text-xs font-black uppercase text-market-muted">{q.product_name}</p><p className="mt-1 font-bold">{q.question}</p></div><span className="text-xs text-market-muted">{date(q.created_at)}</span></div><div className="mt-3 flex flex-col gap-2 sm:flex-row"><input value={answers[q.id]??""} onChange={e=>setAnswers(v=>({...v,[q.id]:e.target.value.slice(0,1500)}))} maxLength={1500} placeholder="Answer this customer question" className="h-11 flex-1 rounded-xl border border-market-line px-3 text-sm"/><Button type="button" disabled={(answers[q.id]??"").trim().length<2} onClick={()=>void answer(q)}>Publish answer</Button></div></div>)}</div>}</Card><Card title="Operations" wide><div className="grid gap-3 sm:grid-cols-4">{["paid","confirmed","fulfilling","shipped"].map(s=><div key={s} className="rounded-xl bg-market-soft p-4"><p className="text-xs font-bold uppercase text-market-muted">{s}</p><p className="mt-2 text-2xl font-black">{m.recentOrders.filter(o=>o.status===s).length}</p></div>)}</div><p className="mt-5 text-sm leading-6 text-market-muted">Payment collection, settlement and refunds remain with the configured payment provider. Merchant operations stay ownership-scoped and database-authoritative.</p></Card></div>}

function Products({m,run,busy,taxonomy}:{m:Merchant;run:RunAction;busy:boolean;taxonomy:ActiveCatalogGroup[]}){
 const [editing,setEditing]=useState<MerchantProduct|null>(null);
 const [form,setForm]=useState<ProductEditForm>({attributes:{},name:"",category:"",subcategory:"",brand:"",model:"",sku:"",price:"",description:"",returnable:true,returnWindowDays:"30",warrantyMonths:"0",fulfillmentType:"delivery"});
 const [newName,setNewName]=useState("");
 const [newCategory,setNewCategory]=useState(taxonomy[0]?.key??"");
 const [newSubcategory,setNewSubcategory]=useState("");
 const [newPrice,setNewPrice]=useState("");
 const [imageProductId,setImageProductId]=useState(m.products[0]?.id??"");
 const imageProduct=m.products.find(p=>p.id===imageProductId)??m.products[0];
 const [bulkRows,setBulkRows]=useState<Array<{name:string;category:(typeof CATALOG_GROUPS)[number]["key"];subcategory?:string;brand?:string;model?:string;sku?:string;price:number;stock:number;description:string;listingType:"product"|"food"|"stay"}>>([]);
 const [bulkError,setBulkError]=useState<string|null>(null);
 const createSubcategories=taxonomy.find(group=>group.key===newCategory)?.subcategories??[];
 const editSubcategories=taxonomy.find(group=>group.key===form.category)?.subcategories??[];
 const categoryIsCanonical=taxonomy.some(group=>group.key===form.category);
 function open(p:MerchantProduct){setEditing(p);setForm({attributes:p.attributes??{},name:p.name,category:p.category,subcategory:p.subcategory??"",brand:p.brand??"",model:p.model??"",sku:p.sku??"",price:p.price,description:p.description??"",returnable:p.returnable,returnWindowDays:p.return_window_days==null?"":String(p.return_window_days),warrantyMonths:p.warranty_months==null?"":String(p.warranty_months),fulfillmentType:p.fulfillment_type});}
 return <div className="space-y-5">
  <Card title="Create listing"><form className="grid gap-3 sm:grid-cols-2 lg:grid-cols-5" onSubmit={e=>{e.preventDefault();void run(()=>createMerchantListing({data:{merchantId:m.merchant_id,name:newName,category:newCategory,subcategory:newSubcategory||undefined,price:Number(newPrice),stock:0,description:""}}),"Listing submitted for review").then(()=>{setNewName("");setNewCategory(taxonomy[0]?.key??"");setNewSubcategory("");setNewPrice("")})}}>
   <input required minLength={3} value={newName} onChange={e=>setNewName(e.target.value)} placeholder="Product name" className="h-11 rounded-xl border border-market-line px-3"/>
   <select required aria-label="Category" value={newCategory} onChange={e=>{setNewCategory(e.target.value as typeof newCategory);setNewSubcategory("")}} className="h-11 rounded-xl border border-market-line px-3">{taxonomy.map(group=><option key={group.key} value={group.key}>{group.name}</option>)}</select>
   <select aria-label="Subcategory" value={newSubcategory} onChange={e=>setNewSubcategory(e.target.value)} className="h-11 rounded-xl border border-market-line px-3"><option value="">Subcategory (optional)</option>{createSubcategories.map(sub=><option key={sub.key} value={sub.key}>{sub.name}</option>)}</select>
   <input required type="number" min="0.01" step="0.01" value={newPrice} onChange={e=>setNewPrice(e.target.value)} placeholder="GHS price" className="h-11 rounded-xl border border-market-line px-3"/>
   <Button disabled={busy}>Add product</Button>
  </form></Card>
  <Card title="Bulk catalogue import"><p className="mb-3 text-sm leading-6 text-market-muted">Upload a UTF-8 CSV exported from Excel/Sheets. Required columns: <b>name, category, price, stock</b>. Optional: subcategory, brand, model, sku, description, listingType. Every row is server-validated and enters pending review.</p><input type="file" accept=".csv,text/csv" onChange={async e=>{setBulkError(null);setBulkRows([]);const file=e.target.files?.[0];if(!file)return;if(file.size>1024*1024){setBulkError("CSV must be 1 MB or smaller.");return;}try{const text=await file.text();const parsed=parseProductCsv(text);setBulkRows(parsed);}catch(err){setBulkError(err instanceof Error?err.message:"Could not read CSV.");}}} className="block w-full text-sm"/>{bulkError&&<p role="alert" className="mt-3 rounded-xl bg-red-50 p-3 text-sm font-semibold text-red-700">{bulkError}</p>}{bulkRows.length>0&&<div className="mt-3 flex flex-wrap items-center justify-between gap-3 rounded-xl bg-market-soft p-3"><span className="text-sm font-bold">{bulkRows.length} validated row{bulkRows.length===1?"":"s"} ready</span><Button disabled={busy} onClick={()=>void run(()=>bulkCreateMerchantListings({data:{merchantId:m.merchant_id,rows:bulkRows}}),`${bulkRows.length} listings submitted for review`)}>Import listings</Button></div>}</Card>
  <Card title={`Customer questions · ${m.productQuestions.length}`}><div className="space-y-3">{m.productQuestions.length?m.productQuestions.map(q=><MerchantQuestion key={q.id} q={q} merchantId={m.merchant_id} run={run} busy={busy}/>):<p className="text-sm text-market-muted">No unanswered customer questions.</p>}</div></Card>
  <Card title={`My item listings · ${m.products.length} shown`}><div className="overflow-x-auto"><table className="w-full text-left text-sm"><thead><tr className="border-b border-market-line text-xs uppercase text-market-muted"><th className="py-3">Product</th><th>Status</th><th>Price</th><th>Stock</th><th></th></tr></thead><tbody>{m.products.map((p:MerchantProduct)=><tr key={p.id} className="border-b border-market-line"><td className="py-3"><p className="font-bold">{p.name}</p><p className="text-xs text-market-muted">{p.sku??"No SKU"} · {p.category}</p></td><td>{p.status}</td><td>GHS {money(p.price)}</td><td>{p.stock}</td><td className="text-right"><Button className="bg-black text-white" onClick={()=>open(p)}>Edit</Button>{p.status!=="archived"?<Button className="ml-2 bg-market-soft text-market-ink" disabled={busy} onClick={()=>void run(()=>archiveMerchantProduct({data:{merchantId:m.merchant_id,productId:p.id}}),"Product archived")}>Archive</Button>:null}</td></tr>)}</tbody></table></div></Card>
  <Card title="Product photos & storage">
    <p className="mb-3 text-sm leading-6 text-market-muted">Upload real product photos securely to configured object storage. Create your listing first, then attach up to eight verified pictures. Each image must be 560 KB or smaller.</p>
    {m.products.length?<>
      <label className="mb-4 block text-sm font-bold">Select listing
        <select value={imageProduct?.id??""} onChange={e=>setImageProductId(e.target.value)} className="mt-1 h-11 w-full rounded-xl border border-market-line px-3">
          {m.products.map(p=><option value={p.id} key={p.id}>{p.name} · {p.status}</option>)}
        </select>
      </label>
      {imageProduct?<MerchantProductImageManager key={imageProduct.id} merchantId={m.merchant_id} productId={imageProduct.id} productName={imageProduct.name} existing={m.productMedia.filter(p=>p.product_id===imageProduct.id)} canEdit={imageProduct.status!=="archived"&&imageProduct.status!=="suspended"&&m.catalog_source!=="enterprise_api"}/>:null}
    </>:<p className="text-sm text-market-muted">Create a product listing to begin uploading its photographs.</p>}
  </Card>
  {editing?<Card title={`Edit · ${editing.name}`}><form className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3" onSubmit={e=>{e.preventDefault();void run(()=>updateMerchantProduct({data:{merchantId:m.merchant_id,productId:editing.id,name:form.name,category:form.category as (typeof CATALOG_GROUPS)[number]["key"],subcategory:form.subcategory||undefined,brand:form.brand||undefined,model:form.model||undefined,sku:form.sku||undefined,price:Number(form.price),description:form.description,returnable:form.returnable,returnWindowDays:form.returnWindowDays===""?null:Number(form.returnWindowDays),warrantyMonths:form.warrantyMonths===""?null:Number(form.warrantyMonths),fulfillmentType:form.fulfillmentType as "delivery"|"pickup"|"delivery_and_pickup",attributes:form.attributes}}),"Product saved and queued for review").then(()=>setEditing(null))}}>
    {[ ["name","Name"],["brand","Brand"],["model","Model"],["sku","SKU"],["price","Price"],["returnWindowDays","Return days"],["warrantyMonths","Warranty months"] ].map(([k,l])=><label key={k} className="text-sm font-bold">{l}<input value={String(form[k as keyof ProductEditForm])} onChange={e=>setForm(prev=>({...prev,[k]:e.target.value} as ProductEditForm))} type={k==="price"||k.includes("Days")||k.includes("Months")?"number":"text"} className="mt-1 h-11 w-full rounded-xl border border-market-line px-3"/></label>)}
    <label className="text-sm font-bold">Category<select value={categoryIsCanonical?form.category:""} onChange={e=>setForm({...form,category:e.target.value,subcategory:""})} required className="mt-1 h-11 w-full rounded-xl border border-market-line px-3"><option value="" disabled>{categoryIsCanonical?"Select category":"Select a canonical category"}</option>{taxonomy.map(group=><option key={group.key} value={group.key}>{group.name}</option>)}</select>{!categoryIsCanonical?<span className="mt-1 block text-xs font-medium text-amber-700">This legacy listing uses “{form.category}”. Choose a marketplace category before saving.</span>:null}</label>
    <label className="text-sm font-bold">Subcategory<select value={categoryIsCanonical?form.subcategory:""} onChange={e=>setForm({...form,subcategory:e.target.value})} disabled={!categoryIsCanonical} className="mt-1 h-11 w-full rounded-xl border border-market-line px-3"><option value="">None</option>{editSubcategories.map(sub=><option key={sub.key} value={sub.key}>{sub.name}</option>)}</select></label>
    <label className="text-sm font-bold">Fulfilment<select value={form.fulfillmentType} onChange={e=>setForm({...form,fulfillmentType:e.target.value as ProductEditForm["fulfillmentType"]})} className="mt-1 h-11 w-full rounded-xl border border-market-line px-3"><option value="delivery">Delivery</option><option value="pickup">Pickup</option><option value="delivery_and_pickup">Delivery + pickup</option></select></label>
    <label className="flex items-center gap-2 pt-7 text-sm font-bold"><input type="checkbox" checked={form.returnable} onChange={e=>setForm({...form,returnable:e.target.checked})}/> Returnable</label>
    {(REQUIRED_PRODUCT_ATTRIBUTES[form.subcategory]??[]).length>0?<fieldset className="sm:col-span-2 lg:col-span-3 rounded-xl border border-market-line p-4"><legend className="px-2 text-sm font-black">Required product specifications</legend><p className="mb-4 text-xs text-market-muted">These details must be completed before marketplace approval. Measurements must be positive numbers.</p><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{REQUIRED_PRODUCT_ATTRIBUTES[form.subcategory].map(k=>{const raw=form.attributes[k];const numeric=NUMERIC_PRODUCT_ATTRIBUTES.has(k);return <label key={k} className="text-sm font-bold">{k.replaceAll("_"," ")}<input value={raw==null?"":String(raw)} type={numeric?"number":"text"} step={numeric?"any":undefined} min={numeric?"0.01":undefined} onChange={e=>setForm(previous=>{const attributes={...previous.attributes};if(!e.target.value)delete attributes[k];else attributes[k]=numeric?Number(e.target.value):e.target.value;return {...previous,attributes}})} className="mt-1 h-11 w-full rounded-xl border border-market-line px-3"/></label>})}</div></fieldset>:null}
    <label className="sm:col-span-2 text-sm font-bold">Description<textarea value={form.description} onChange={e=>setForm({...form,description:e.target.value})} className="mt-1 min-h-24 w-full rounded-xl border border-market-line p-3"/></label>
    <div className="sm:col-span-2 flex gap-2"><Button disabled={busy||!categoryIsCanonical}>Save changes</Button><Button type="button" className="bg-market-soft text-market-ink" onClick={()=>setEditing(null)}>Close</Button></div>
   </form></Card>:null}
 </div>
}

function MerchantQuestion({q,merchantId,run,busy}:{q:{id:string;product_name:string;question:string;created_at:string};merchantId:string;run:RunAction;busy:boolean}){const [answer,setAnswer]=useState("");return <div className="rounded-xl border border-market-line p-4"><p className="text-xs font-black uppercase text-market-muted">{q.product_name}</p><p className="mt-1 font-bold">{q.question}</p><p className="mt-1 text-xs text-market-muted">Asked {date(q.created_at)}</p><form className="mt-3 flex flex-col gap-2 sm:flex-row" onSubmit={e=>{e.preventDefault();void run(()=>answerProductQuestion({data:{merchantId,questionId:q.id,answer}}),"Question answered")}}><input value={answer} onChange={e=>setAnswer(e.target.value)} minLength={2} maxLength={1500} required placeholder="Reply publicly to this product question" className="h-11 flex-1 rounded-xl border border-market-line px-3"/><Button disabled={busy}>Reply</Button></form></div>}

function parseProductCsv(text:string){
 const records=parseCsvRecords(text);
 if(records.length<2)throw new Error("CSV needs a header and at least one product row.");
 const headers=records[0].map(x=>x.toLowerCase());
 if(new Set(headers).size!==headers.length)throw new Error("CSV headers must not be duplicated.");
 for(const required of ["name","category","price","stock"])if(!headers.includes(required))throw new Error(`CSV is missing required column: ${required}`);
 if(records.length-1>200)throw new Error("Import at most 200 products per batch.");
 return records.slice(1).map((cols,index)=>{
  if(cols.length!==headers.length)throw new Error(`Row ${index+2}: expected ${headers.length} fields, got ${cols.length}.`);
  const get=(name:string)=>cols[headers.indexOf(name)]??"";
  const category=get("category") as (typeof CATALOG_GROUPS)[number]["key"];
  const group=CATALOG_GROUPS.find(g=>g.key===category);
  if(!group)throw new Error(`Row ${index+2}: unknown category '${category}'.`);
  const subcategory=get("subcategory")||undefined;
  if(subcategory&&!group.subcategories.some(s=>s.key===subcategory))throw new Error(`Row ${index+2}: subcategory does not belong to ${category}.`);
  const price=Number(get("price")),stock=Number(get("stock"));
  if(!Number.isFinite(price)||price<=0)throw new Error(`Row ${index+2}: invalid price.`);
  if(!Number.isInteger(stock)||stock<0)throw new Error(`Row ${index+2}: invalid stock.`);
  const listingRaw=get("listingtype")||get("listing_type")||"product";
  if(!["product","food","stay"].includes(listingRaw))throw new Error(`Row ${index+2}: invalid listingType.`);
  return {name:get("name"),category,subcategory,brand:get("brand")||undefined,model:get("model")||undefined,sku:get("sku")||undefined,price,stock,description:get("description"),listingType:listingRaw as "product"|"food"|"stay"};
 });
}

function Inventory({m,run,busy}:{m:Merchant;run:RunAction;busy:boolean}){const [productId,setProductId]=useState(m.products[0]?.id??"");const [variantId,setVariantId]=useState("");const [delta,setDelta]=useState("");const [reason,setReason]=useState("");const variants=m.variants.filter((v:MerchantVariant)=>v.product_id===productId);return <div className="grid gap-5 lg:grid-cols-2"><Card title="Inventory control"><form className="space-y-3" onSubmit={e=>{e.preventDefault();void run(()=>adjustMerchantInventory({data:{merchantId:m.merchant_id,productId,variantId:variantId||null,delta:Number(delta),reason}}),"Inventory updated")}}><label className="block text-sm font-bold">Product<select value={productId} onChange={e=>{setProductId(e.target.value);setVariantId("")}} className="mt-1 h-11 w-full rounded-xl border border-market-line px-3">{m.products.map((p:MerchantProduct)=><option key={p.id} value={p.id}>{p.name} · {p.stock} total</option>)}</select></label>{variants.length?<label className="block text-sm font-bold">Variant<select value={variantId} onChange={e=>setVariantId(e.target.value)} className="mt-1 h-11 w-full rounded-xl border border-market-line px-3"><option value="">Select variant</option>{variants.map((v:MerchantVariant)=><option key={v.id} value={v.id}>{v.sku} · {v.stock}</option>)}</select></label>:null}<label className="block text-sm font-bold">Adjustment (+ receive, − remove)<input required type="number" step="1" value={delta} onChange={e=>setDelta(e.target.value)} className="mt-1 h-11 w-full rounded-xl border border-market-line px-3"/></label><label className="block text-sm font-bold">Reason<input required minLength={3} maxLength={240} value={reason} onChange={e=>setReason(e.target.value)} placeholder="New stock received" className="mt-1 h-11 w-full rounded-xl border border-market-line px-3"/></label><Button disabled={busy||!productId||(!variantId&&variants.length>0)}>Apply inventory change</Button></form></Card><Card title="Recent inventory changes"><div className="space-y-3">{m.inventoryHistory.map((x:Merchant["inventoryHistory"][number])=><div key={x.id} className="border-b border-market-line pb-3"><div className="flex justify-between gap-3"><b>{x.delta>0?`+${x.delta}`:x.delta}</b><span className="text-xs text-market-muted">{date(x.created_at)}</span></div><p className="text-sm">{x.reason}</p><p className="text-xs text-market-muted">{x.product_id}{x.variant_id?` · ${x.variant_id}`:""}</p></div>)}</div></Card><Card title="Stock board" wide><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{m.products.map((p:MerchantProduct)=><div key={p.id} className="rounded-xl border border-market-line p-4"><p className="font-bold">{p.name}</p><p className="mt-2 text-2xl font-black">{p.stock}</p><p className="text-xs text-market-muted">{p.stock===0?"Out of stock":p.stock<5?"Low stock":"Available"}</p></div>)}</div></Card></div>}
function Orders({m,run,busy}:{m:Merchant;run:RunAction;busy:boolean}){
 const [query,setQuery]=useState("");
 const filtered=m.recentOrders.filter(o=>`${o.id} ${o.status} ${o.address}`.toLowerCase().includes(query.toLowerCase()));
 const next=(s:string)=>s==="paid"?"confirmed":s==="confirmed"?"fulfilling":s==="fulfilling"?"shipped":s==="shipped"?"delivered":s==="delivered"?"completed":null;
 return <Card title={`Order operations · ${filtered.length} shown`}><div className="mb-4 flex flex-wrap gap-3"><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search order, status or address" className="h-11 min-w-64 flex-1 rounded-xl border border-market-line px-3"/><span className="rounded-xl bg-market-soft px-3 py-2 text-xs font-bold">Provider settlement · no ELEMARKET custody</span></div><div className="space-y-3">{filtered.map((o:MerchantOrder)=>{const n=next(o.status);return <div key={o.id} className="rounded-xl border border-market-line p-4"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="font-black">{o.id}</p><p className="text-xs text-market-muted">{date(o.created_at)} · {o.address}</p></div><span className="rounded-full bg-market-soft px-3 py-1 text-xs font-bold">{o.status}</span></div><div className="mt-3 grid gap-3 sm:grid-cols-3"><div><p className="text-xs font-bold text-market-muted">Order value</p><p className="font-black">GHS {money(o.grand_total)}</p></div><div><p className="text-xs font-bold text-market-muted">Delivered</p><p className="font-bold">{o.delivered_at?date(o.delivered_at):"Not delivered"}</p></div><div><p className="text-xs font-bold text-market-muted">Provider withdrawal eligibility</p><p className={`font-black ${o.withdrawal_eligible?"text-market-green":""}`}>{o.withdrawal_eligible?"Eligible":o.withdrawal_reason.replaceAll("_"," ")}</p>{o.eligible_at?<p className="text-xs text-market-muted">Eligibility time: {date(o.eligible_at)}</p>:null}</div></div>{o.dispute_filed_at?<p className="mt-3 rounded-lg bg-market-soft p-2 text-xs font-semibold">Customer dispute recorded: {date(o.dispute_filed_at)}</p>:null}<div className="mt-3 flex flex-wrap items-center justify-between gap-3">{n?<Button disabled={busy} onClick={()=>void run(()=>advanceMerchantOrder({data:{merchantId:m.merchant_id,orderId:o.id,toStatus:n as "confirmed"|"fulfilling"|"shipped"|"delivered"|"completed"}}),`Order moved to ${n}`)}>Mark {n}</Button>:<span className="text-xs font-bold text-market-muted">No merchant action available</span>}</div></div>})}{!filtered.length?<p className="py-8 text-center text-sm text-market-muted">No orders match your search.</p>:null}</div></Card>}
function Finance({m}:{m:Merchant}){
 const e=m.finance.balance.providerWithdrawalEligibility;const h=m.merchantHealth as JsonObject|null;
 const [providerId,setProviderId]=useState(m.merchantFinancingProviders[0]?.id??""); const [amount,setAmount]=useState(""); const [status,setStatus]=useState<string|null>(null); const [busy,setBusy]=useState(false);
 async function apply(){const requestedAmount=Number(amount);if(!providerId||!Number.isFinite(requestedAmount)||requestedAmount<=0){setStatus("Choose a financing provider and enter a valid amount.");return}setBusy(true);setStatus(null);try{const r=await startMerchantFinancing({data:{merchantId:m.merchant_id,providerId,requestedAmount,idempotencyKey:`mfa_${crypto.randomUUID().replaceAll("-","")}`}});setStatus(`Application ${r.applicationId} started. The provider must independently review and approve it.`);setAmount("")}catch{setStatus("The financing application could not be started. Check the provider amount range and availability.")}finally{setBusy(false)}}
 return <div className="grid gap-5 lg:grid-cols-2"><Card title="Merchant Health for Financing Providers"><p className="text-xs font-black uppercase text-market-muted">Marketplace performance signal · provider underwriting remains independent</p>{h?<><div className="mt-4 grid gap-3 sm:grid-cols-3"><div className="rounded-xl bg-market-soft p-4"><p className="text-xs font-bold text-market-muted">Health score</p><p className="mt-2 text-2xl font-black">{String(h.score??"—")}/1000</p></div><div className="rounded-xl bg-market-soft p-4"><p className="text-xs font-bold text-market-muted">Data status</p><p className="mt-2 text-xl font-black capitalize">{String(h.freshness_status??"unknown")}</p></div><div className="rounded-xl bg-market-soft p-4"><p className="text-xs font-bold text-market-muted">Data points</p><p className="mt-2 text-xl font-black">{String(h.sample_size??0)}</p></div></div><p className="mt-4 text-sm leading-6 text-market-muted">This score reflects verified ELEMARKET marketplace health signals. Financing providers make their own credit, amount, pricing and repayment decisions.</p></>:<p className="mt-4 text-sm leading-6 text-market-muted">Not enough verified marketplace history to calculate a provider-facing health score yet.</p>}</Card><Card title="Business financing"><p className="text-sm leading-6 text-market-muted">Apply only through financing partners currently enabled on ELEMARKET. A listing here is not an approval, guarantee or ELEMARKET loan.</p>{m.merchantFinancingProviders.length?<div className="mt-4 space-y-3"><select value={providerId} onChange={x=>setProviderId(x.target.value)} className="h-11 w-full rounded-xl border border-market-line px-3">{m.merchantFinancingProviders.map(p=><option key={p.id} value={p.id}>{p.name} · {p.product_type.replaceAll("_"," ")}</option>)}</select><input inputMode="decimal" value={amount} onChange={x=>setAmount(x.target.value.replace(/[^0-9.]/g,"").slice(0,16))} placeholder="Requested amount (GHS)" className="h-11 w-full rounded-xl border border-market-line px-3"/><div className="text-xs text-market-muted">{(()=>{const p=m.merchantFinancingProviders.find(x=>x.id===providerId);if(!p)return null;return <>{p.provider_legal_name?<p>Provider: {p.provider_legal_name}</p>:null}<p>{p.minimum_application_amount?`Minimum GHS ${money(p.minimum_application_amount)}`:"No provider minimum recorded"}{p.maximum_application_amount?` · Maximum GHS ${money(p.maximum_application_amount)}`:""}</p><p className="mt-1">{p.terms_url?<a href={p.terms_url} target="_blank" rel="noreferrer" className="underline">Terms</a>:null}{p.privacy_url?<> · <a href={p.privacy_url} target="_blank" rel="noreferrer" className="underline">Privacy</a></>:null}</p></>})()}</div><Button type="button" disabled={busy} onClick={()=>void apply()}>{busy?"Starting application…":"Apply with selected provider"}</Button>{status?<p role="status" className="rounded-xl bg-market-soft p-3 text-xs font-semibold">{status}</p>:null}</div>:<p className="mt-4 text-sm text-market-muted">No merchant-financing partner is currently enabled.</p>}</Card><Card title="Financing applications" wide><div className="mt-3 space-y-3">{m.merchantFinancingApplications.length?m.merchantFinancingApplications.map(a=><div key={a.id} className="flex flex-wrap items-center justify-between gap-3 border-b border-market-line pb-3"><div><b>{a.provider_name}</b><p className="text-xs text-market-muted">GHS {money(a.requested_amount)} · {a.status.replaceAll("_"," ")} · {date(a.created_at)}</p></div>{a.redirect_url?<a href={a.redirect_url} target="_blank" rel="noreferrer" className="rounded-xl border border-market-line px-3 py-2 text-xs font-black">Continue with provider</a>:null}</div>):<p className="text-sm text-market-muted">No merchant financing applications yet.</p>}</div></Card><Card title="Payment & settlement"><p className="text-xs font-black uppercase text-market-muted">Provider-managed</p><div className="mt-4 grid gap-3 sm:grid-cols-3">{[["Sales",m.finance.balance.totalSales],["Platform commission",m.finance.balance.platformCommission],["Merchant order value",m.finance.balance.merchantOrderValue]].map(([a,b])=><div key={String(a)} className="rounded-xl bg-market-soft p-4"><p className="text-xs font-bold text-market-muted">{a}</p><p className="mt-2 text-xl font-black">GHS {money(String(b))}</p></div>)}</div><p className="mt-4 text-sm leading-6 text-market-muted">Payment collection, settlement and refunds are handled by the configured payment provider. ELEMARKET does not hold, release, or pay out customer funds.</p></Card><Card title="Provider withdrawal eligibility"><div className="mt-4 grid gap-3 sm:grid-cols-3"><div className="rounded-xl bg-market-soft p-4"><p className="text-xs font-bold text-market-muted">Eligible sales</p><p className="mt-2 text-xl font-black">GHS {money(String(e.eligibleAmount))}</p></div><div className="rounded-xl bg-market-soft p-4"><p className="text-xs font-bold text-market-muted">Eligible orders</p><p className="mt-2 text-xl font-black">{e.eligibleOrders}</p></div><div className="rounded-xl bg-market-soft p-4"><p className="text-xs font-bold text-market-muted">Active disputes</p><p className="mt-2 text-xl font-black">{e.activeDisputes}</p></div></div><p className="mt-4 text-sm leading-6 text-market-muted">A delivered sale is provider-withdrawal eligible only after 24 hours have elapsed from its recorded delivery transition with no customer dispute filed during that window. ELEMARKET does not execute the withdrawal.</p></Card><Card title="Provider refunds"><div className="space-y-3 mt-4">{m.finance.refundRequests.length?m.finance.refundRequests.map((x:MerchantFinance["refundRequests"][number])=><div key={x.id} className="border-b border-market-line pb-3"><b>{x.orderId}</b><p className="text-sm">GHS {money(x.amount)} · {x.status.replaceAll("_"," ")}</p><p className="text-xs text-market-muted">{x.reason}</p></div>):<p className="text-sm text-market-muted">No provider refund requests for this merchant.</p>}</div></Card></div>
}
function Business({m,run,busy,taxonomy}:{m:Merchant;run:RunAction;busy:boolean;taxonomy:ActiveCatalogGroup[]}){const [f,setF]=useState({...m.profile,categories:taxonomy.map(group=>group.key).filter(key=>m.profile.categories.includes(key))});return <Card title="Business profile"><form className="grid gap-3 sm:grid-cols-2" onSubmit={e=>{e.preventDefault();void run(()=>updateMerchantProfile({data:{merchantId:m.merchant_id,name:f.name,categories:f.categories,description:f.description,address:f.address,city:f.city,neighborhood:f.neighborhood}}),"Business profile updated")}}><label className="text-sm font-bold">Business name<input value={f.name} onChange={e=>setF({...f,name:e.target.value})} className="mt-1 h-11 w-full rounded-xl border border-market-line px-3"/></label><label className="text-sm font-bold">City<input value={f.city} onChange={e=>setF({...f,city:e.target.value})} className="mt-1 h-11 w-full rounded-xl border border-market-line px-3"/></label><label className="text-sm font-bold">Neighborhood<input value={f.neighborhood} onChange={e=>setF({...f,neighborhood:e.target.value})} className="mt-1 h-11 w-full rounded-xl border border-market-line px-3"/></label><label className="text-sm font-bold sm:col-span-2">Address<input value={f.address} onChange={e=>setF({...f,address:e.target.value})} className="mt-1 h-11 w-full rounded-xl border border-market-line px-3"/></label><label className="text-sm font-bold sm:col-span-2">Description<textarea value={f.description} onChange={e=>setF({...f,description:e.target.value})} className="mt-1 min-h-24 w-full rounded-xl border border-market-line p-3"/></label><fieldset className="sm:col-span-2"><legend className="text-sm font-bold">Catalogue categories</legend><p className="mt-1 text-xs text-market-muted">Choose all catalogues your business operates in. Individual listings still require their own valid category.</p><div className="mt-3 grid gap-2 sm:grid-cols-2 lg:grid-cols-3">{taxonomy.map(group=>{const checked=f.categories.includes(group.key);return <label key={group.key} className={`flex items-start gap-2 rounded-xl border p-3 text-sm ${checked?"border-market-green bg-green-50":"border-market-line"}`}><input type="checkbox" checked={checked} onChange={()=>setF({...f,categories:checked?f.categories.filter(key=>key!==group.key):[...f.categories,group.key]})} className="mt-0.5"/><span><b>{group.name}</b><span className="block text-xs text-market-muted">{group.blurb}</span></span></label>})}</div>{f.categories.length===0?<p className="mt-2 text-xs font-semibold text-red-700">Select at least one category.</p>:null}</fieldset><Button disabled={busy||f.categories.length===0}>Save business profile</Button></form></Card>}
function Kyb({m}:{m:Merchant}){const k=m.kyb;return <div className="grid gap-5 lg:grid-cols-2"><Card title="KYB status">{k?<div className="mt-4 space-y-3 text-sm"><Row a="Application" b={k.status}/><Row a="Business verification" b={k.check_status??"not started"}/><Row a="Registration number" b={k.registration_number??"Not supplied"}/><Row a="Business type" b={k.business_type??"Pending"}/><Row a="Tax registration" b={k.tax_registration_status??"Pending"}/><Row a="VAT registration" b={k.vat_registration_status??"Pending"}/><Row a="Settlement method" b={k.settlement_method??"Pending"}/></div>:<p className="mt-4 text-sm text-market-muted">No merchant application record was found for this workspace.</p>}</Card><Card title="Compliance boundary"><p className="mt-4 text-sm leading-6 text-market-muted">Merchant users can view compliance state, but cannot approve themselves or alter verification decisions. Verification evidence remains in the KYB/provider workflow.</p></Card></div>}
function Row({a,b}:{a:string;b:string|null}){return <div className="flex justify-between gap-4 border-b border-market-line pb-2"><span className="text-market-muted">{a}</span><b className="text-right">{b}</b></div>}
function Promotions({m,run,busy}:{m:Merchant;run:RunAction;busy:boolean}){return <Card title="Promotions"><div className="space-y-3 mt-4">{m.promotions.map((p)=><div key={p.promotionId} className="rounded-xl border border-market-line p-4"><div className="flex justify-between gap-3"><div><b>{p.name}</b><p className="text-xs text-market-muted">{date(p.startsAt)} → {date(p.endsAt)}</p></div><span className="text-xs font-bold">{p.participationStatus??"not joined"}</span></div><div className="mt-3 flex gap-2">{p.participationStatus==="accepted"?<Button className="bg-market-soft text-market-ink" disabled={busy} onClick={()=>void run(()=>withdrawMerchantPromotionParticipation({data:{merchantId:m.merchant_id,promotionId:p.promotionId}}),"Promotion participation withdrawn")}>Withdraw</Button>:<Button disabled={busy} onClick={()=>void run(()=>setMerchantPromotionParticipation({data:{merchantId:m.merchant_id,promotionId:p.promotionId,accept:true}}),"Promotion accepted")}>Join promotion</Button>}</div></div>)}{!m.promotions.length?<p className="text-sm text-market-muted">No active merchant promotions.</p>:null}</div></Card>}

function Advertising({m}:{m:Merchant}){
 const eligible=m.products.filter(p=>p.status==="active"); const [campaigns,setCampaigns]=useState<Array<{id:string;product_id:string;product_name:string;name:string;title:string;subtitle:string|null;placement:string;status:string;starts_at:string;ends_at:string;target_city:string|null;priority:number;impression_count:number;click_count:number;rejection_reason:string|null}>>([]); const [productId,setProductId]=useState(eligible[0]?.id??""); const [title,setTitle]=useState(""); const [subtitle,setSubtitle]=useState(""); const [placement,setPlacement]=useState<"sponsored_ads"|"food_spotlight">("sponsored_ads"); const [startsAt,setStartsAt]=useState(""); const [endsAt,setEndsAt]=useState(""); const [targetCity,setTargetCity]=useState(""); const [busy,setBusy]=useState(false); const [error,setError]=useState<string|null>(null);
 const refresh = React.useCallback(async () => { try { setCampaigns(await listMerchantAdCampaigns({ data: { merchantId: m.merchant_id } })); setError(null); } catch (e) { setError(safeError(e)); } }, [m.merchant_id]);
 React.useEffect(() => { void refresh(); }, [refresh]);
 async function submit(e:FormEvent){e.preventDefault();setBusy(true);setError(null);try{if(!productId)throw new Error("Choose an active product");if(!startsAt||!endsAt)throw new Error("Choose a campaign start and end time");await createHomepageAdCampaign({data:{merchantId:m.merchant_id,productId,name:title.trim(),title:title.trim(),subtitle:subtitle.trim()||undefined,startsAt:new Date(startsAt).toISOString(),endsAt:new Date(endsAt).toISOString(),targetCity:targetCity.trim()||undefined,priority:100,placement}});setTitle("");setSubtitle("");setTargetCity("");await refresh()}catch(e){setError(safeError(e))}finally{setBusy(false)}}
 return <div className="grid gap-5 lg:grid-cols-2"><Card title="Create advertising campaign"><p className="text-sm leading-6 text-market-muted">Promote an active listing in approved homepage placements. Every campaign is reviewed by ELEMARKET before it can appear publicly; creating a campaign does not guarantee placement or traffic.</p>{eligible.length===0?<p className="mt-4 rounded-xl bg-market-soft p-4 text-sm font-semibold">Publish at least one active product before creating an ad.</p>:<form onSubmit={submit} className="mt-4 space-y-3"><label className="block text-sm font-bold">Product<select value={productId} onChange={e=>setProductId(e.target.value)} className="mt-1 h-11 w-full rounded-xl border border-market-line px-3">{eligible.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></label><label className="block text-sm font-bold">Placement<select value={placement} onChange={e=>setPlacement(e.target.value as typeof placement)} className="mt-1 h-11 w-full rounded-xl border border-market-line px-3"><option value="sponsored_ads">Sponsored products</option><option value="food_spotlight">Food spotlight</option></select></label><label className="block text-sm font-bold">Campaign title<input required minLength={2} maxLength={120} value={title} onChange={e=>setTitle(e.target.value)} className="mt-1 h-11 w-full rounded-xl border border-market-line px-3" placeholder="Weekend deal"/></label><label className="block text-sm font-bold">Short message <span className="font-normal text-market-muted">(optional)</span><textarea maxLength={180} value={subtitle} onChange={e=>setSubtitle(e.target.value)} className="mt-1 min-h-20 w-full rounded-xl border border-market-line p-3" placeholder="Tell shoppers why this product is worth opening"/></label><div className="grid gap-3 sm:grid-cols-2"><label className="text-sm font-bold">Starts<input required type="datetime-local" value={startsAt} onChange={e=>setStartsAt(e.target.value)} className="mt-1 h-11 w-full rounded-xl border border-market-line px-3"/></label><label className="text-sm font-bold">Ends<input required type="datetime-local" value={endsAt} onChange={e=>setEndsAt(e.target.value)} className="mt-1 h-11 w-full rounded-xl border border-market-line px-3"/></label></div><label className="block text-sm font-bold">Target city <span className="font-normal text-market-muted">(optional)</span><input maxLength={80} value={targetCity} onChange={e=>setTargetCity(e.target.value)} className="mt-1 h-11 w-full rounded-xl border border-market-line px-3" placeholder="Accra"/></label>{error?<p role="alert" className="rounded-xl bg-red-50 p-3 text-sm font-semibold text-red-700">{error}</p>:null}<Button disabled={busy||!productId||!title.trim()}>{busy?"Submitting…":"Submit for review"}</Button></form>}</Card><Card title="Advertising performance"><p className="text-sm leading-6 text-market-muted">Only your own campaigns are shown. Impressions and clicks are marketplace-measured events; approval and scheduling are controlled by ELEMARKET.</p><div className="mt-4 space-y-3">{campaigns.length===0?<p className="text-sm text-market-muted">No advertising campaigns yet.</p>:campaigns.map(c=><div key={c.id} className="rounded-xl border border-market-line p-4"><div className="flex items-start justify-between gap-3"><div><b>{c.title}</b><p className="text-xs text-market-muted">{c.product_name} · {c.placement.replaceAll("_"," ")}</p></div><span className="rounded-full bg-market-soft px-2 py-1 text-[11px] font-black">{c.status.replaceAll("_"," ")}</span></div><div className="mt-3 grid grid-cols-2 gap-2 text-xs"><div className="rounded-lg bg-market-soft p-3"><b>{c.impression_count}</b><p className="text-market-muted">Impressions</p></div><div className="rounded-lg bg-market-soft p-3"><b>{c.click_count}</b><p className="text-market-muted">Clicks</p></div></div>{c.rejection_reason?<p className="mt-3 text-xs font-semibold text-red-700">Review note: {c.rejection_reason}</p>:null}</div>)}</div></Card></div>
}
function Locations({merchantId}:{merchantId:string}){
 const [locations,setLocations]=useState<EnterpriseLocationRow[]>([]); const [staff,setStaff]=useState<EnterpriseStaffRow[]>([]); const [loading,setLoading]=useState(true); const [error,setError]=useState<string|null>(null);
 const [name,setName]=useState(""); const [city,setCity]=useState(""); const [address,setAddress]=useState(""); const [type,setType]=useState<EnterpriseLocationType>("store"); const [externalKey,setExternalKey]=useState(""); const [busy,setBusy]=useState(false);
 const [staffEmail,setStaffEmail]=useState(""); const [staffRole,setStaffRole]=useState<EnterpriseStaffRole>("operations_manager"); const [staffLocation,setStaffLocation]=useState("");
 const locationScopedRoles=new Set<EnterpriseStaffRole>(["location_manager","warehouse_operator","inventory_manager","fulfillment_operator"]);
 const refresh = React.useCallback(async () => { setLoading(true); try { const [nextLocations, nextStaff] = await Promise.all([loadEnterpriseLocations({ data: { merchantId } }), loadEnterpriseStaff({ data: { merchantId } })]); setLocations(nextLocations); setStaff(nextStaff); setError(null); } catch (e) { setError(safeError(e)); } finally { setLoading(false); } }, [merchantId]);
 React.useEffect(() => { void refresh(); }, [refresh]);
 async function create(){setBusy(true);try{await createEnterpriseLocationFn({data:{merchantId,name,address,city,locationType:type,externalLocationKey:externalKey||undefined}});setName("");setCity("");setAddress("");setExternalKey("");await refresh()}catch(e){setError(safeError(e))}finally{setBusy(false)}}
 async function assignStaff(status:"active"|"suspended"|"revoked"="active",row?:EnterpriseStaffRow){
  setBusy(true); setError(null);
  try{
   const role=row?.role??staffRole; const locationId=row?.location_id??(locationScopedRoles.has(role)?staffLocation:null);
   if(locationScopedRoles.has(role)&&!locationId) throw new Error("A location is required for this enterprise staff role");
   await setEnterpriseStaffAssignmentFn({data:{merchantId,targetEmail:row?.email??staffEmail,locationId:locationId||null,role,status}});
   if(!row){setStaffEmail("");setStaffLocation("")}
   await refresh();
  }catch(e){setError(safeError(e))}finally{setBusy(false)}
 }
 return <div className="space-y-5">
  <Card title="Enterprise locations"><p className="text-sm leading-6 text-market-muted">Manage stores, warehouses, distribution centers, fulfillment centers and pickup points under one enterprise identity. Structural changes require fresh authentication.</p><div className="mt-4 grid gap-3 md:grid-cols-2 lg:grid-cols-5"><input value={name} onChange={e=>setName(e.target.value)} placeholder="Location name" className="h-11 rounded-xl border border-market-line px-3"/><input value={city} onChange={e=>setCity(e.target.value)} placeholder="City" className="h-11 rounded-xl border border-market-line px-3"/><input value={address} onChange={e=>setAddress(e.target.value)} placeholder="Address" className="h-11 rounded-xl border border-market-line px-3 lg:col-span-2"/><select value={type} onChange={e=>setType(e.target.value as EnterpriseLocationType)} className="h-11 rounded-xl border border-market-line px-3"><option value="store">Store</option><option value="warehouse">Warehouse</option><option value="distribution_center">Distribution center</option><option value="fulfillment_center">Fulfillment center</option><option value="pickup_point">Pickup point</option><option value="office">Office</option><option value="service_center">Service center</option></select><input value={externalKey} onChange={e=>setExternalKey(e.target.value)} placeholder="ERP/POS location key" className="h-11 rounded-xl border border-market-line px-3"/><div className="md:col-span-2 lg:col-span-5"><Button disabled={busy||!name||!city||!address} onClick={()=>void create()}>Add location</Button></div></div>{error?<p className="mt-3 rounded-lg bg-market-soft p-3 text-sm">{error}</p>:null}</Card>
  <Card title="Locations"><div className="overflow-x-auto"><table className="min-w-full text-sm"><thead><tr className="border-b border-market-line text-left"><th className="p-3">Location</th><th className="p-3">Type</th><th className="p-3">City</th><th className="p-3">Available</th><th className="p-3">Reserved</th><th className="p-3">Status</th></tr></thead><tbody>{locations.map(l=><tr key={String(l.id)} className="border-b border-market-line"><td className="p-3 font-bold">{String(l.name)}</td><td className="p-3">{String(l.location_type).replaceAll("_"," ")}</td><td className="p-3">{String(l.city)}</td><td className="p-3">{String(l.available_units??0)}</td><td className="p-3">{String(l.reserved_units??0)}</td><td className="p-3">{String(l.status)}</td></tr>)}</tbody></table>{loading?<p className="p-4 text-sm text-market-muted">Loading locations…</p>:!locations.length?<p className="p-4 text-sm text-market-muted">No enterprise locations configured.</p>:null}</div></Card>
  <Card title="Enterprise staff"><p className="text-sm leading-6 text-market-muted">Assign verified ELEMARKET users to least-privilege enterprise roles. These roles do not grant merchant finance, KYB or profile access.</p><div className="mt-4 grid gap-3 lg:grid-cols-4"><input type="email" value={staffEmail} onChange={e=>setStaffEmail(e.target.value)} placeholder="Verified staff email" className="h-11 rounded-xl border border-market-line px-3"/><select value={staffRole} onChange={e=>{const r=e.target.value as EnterpriseStaffRole;setStaffRole(r);if(!locationScopedRoles.has(r))setStaffLocation("")}} className="h-11 rounded-xl border border-market-line px-3"><option value="operations_manager">Operations manager</option><option value="location_manager">Location manager</option><option value="warehouse_operator">Warehouse operator</option><option value="inventory_manager">Inventory manager</option><option value="fulfillment_operator">Fulfillment operator</option><option value="support_manager">Support manager</option><option value="analyst">Analyst</option><option value="enterprise_admin">Enterprise admin</option></select><select value={staffLocation} disabled={!locationScopedRoles.has(staffRole)} onChange={e=>setStaffLocation(e.target.value)} className="h-11 rounded-xl border border-market-line px-3 disabled:bg-market-soft"><option value="">{locationScopedRoles.has(staffRole)?"Choose location":"Organization-wide"}</option>{locations.map(l=><option key={l.id} value={l.id}>{l.name}</option>)}</select><Button disabled={busy||!staffEmail||locationScopedRoles.has(staffRole)&&!staffLocation} onClick={()=>void assignStaff()}>Assign staff</Button></div><div className="mt-5 overflow-x-auto"><table className="min-w-full text-sm"><thead><tr className="border-b border-market-line text-left"><th className="p-3">Staff</th><th className="p-3">Role</th><th className="p-3">Scope</th><th className="p-3">Status</th><th className="p-3">Action</th></tr></thead><tbody>{staff.map(row=><tr key={row.id} className="border-b border-market-line"><td className="p-3"><b>{row.name}</b><div className="text-xs text-market-muted">{row.email}</div></td><td className="p-3">{row.role.replaceAll("_"," ")}</td><td className="p-3">{row.location_name??"Organization-wide"}</td><td className="p-3">{row.status}</td><td className="p-3"><div className="flex gap-2">{row.status==="active"?<Button className="bg-market-soft text-market-ink" disabled={busy||row.role==="enterprise_admin"&&staff.filter(x=>x.role==="enterprise_admin"&&x.status==="active").length<=1} onClick={()=>void assignStaff("suspended",row)}>Suspend</Button>:<Button disabled={busy} onClick={()=>void assignStaff("active",row)}>Activate</Button>}{row.status!=="revoked"?<Button className="bg-black text-white" disabled={busy||row.role==="enterprise_admin"&&staff.filter(x=>x.role==="enterprise_admin"&&x.status==="active").length<=1} onClick={()=>void assignStaff("revoked",row)}>Revoke</Button>:null}</div></td></tr>)}</tbody></table>{!staff.length&&!loading?<p className="p-4 text-sm text-market-muted">No enterprise staff assignments yet.</p>:null}</div></Card>
 </div>
}

function Enterprise({m,run,busy}:{m:Merchant;run:RunAction;busy:boolean}){
 const existing=m.enterpriseCatalog;
 const [endpoint,setEndpoint]=useState(existing?.endpoint_url??"");
 const [authType,setAuthType]=useState(existing?.auth_type??"bearer");
 const [credential,setCredential]=useState("");
 const [username,setUsername]=useState("");
 const [webhookEnabled,setWebhookEnabled]=useState(existing?.webhook_enabled??false);
 const [webhookSecret,setWebhookSecret]=useState("");
 const [orderEndpoint,setOrderEndpoint]=useState(existing?.order_endpoint_url??"");
 const [orderWebhookSecret,setOrderWebhookSecret]=useState("");
 const [pageSize,setPageSize]=useState(String(existing?.page_size??250));
 const [cursorPath,setCursorPath]=useState(existing?.cursor_path??"");
 const [staleAfter,setStaleAfter]=useState(String(existing?.inventory_stale_after_seconds??900));
 const [mappingJson,setMappingJson]=useState(JSON.stringify({id:"id",sku:"sku",name:"name",description:"description",category:"category",subcategory:"subcategory",brand:"brand",model:"model",price:"price",currency:"currency",stock:"stock",image:"image",warrantyMonths:"warrantyMonths"},null,2));
 const health=m.enterpriseHealth; const ops=m.enterpriseOps;
 function parseMapping(){try{return JSON.parse(mappingJson) as Record<string,string>}catch{throw new Error("Field mapping must be valid JSON")}}
 if(!existing && m.catalogSource!=="enterprise_api") return <Card title="Enterprise operations"><p className="text-sm leading-6 text-market-muted">Enterprise API mode is not enabled for this merchant. An administrator must enable enterprise mode before a catalogue connection can be configured.</p></Card>;
 return <div className="space-y-5">
  <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">{[["Catalog products",health?.products.total??0],["Out of stock",health?.products.out_of_stock??0],["Order events pending",health?.orders.pending??0],["Webhook failures",health?.webhooks.failed??0]].map(([label,value])=><div key={String(label)} className="rounded-2xl border border-market-line bg-white p-4"><p className="text-xs font-bold uppercase text-market-muted">{label}</p><p className="mt-2 text-2xl font-black">{String(value)}</p></div>)}</div>
  <Card title="Enterprise connection"><p className="text-sm leading-6 text-market-muted">Enterprise inventory is externally authoritative. Credentials are encrypted server-side. Marketplace settlement remains provider-managed; ELEMARKET does not custody funds.</p><form className="mt-4 grid gap-3 lg:grid-cols-2" onSubmit={e=>{e.preventDefault();void run(()=>{const fieldMapping=parseMapping();return configureEnterpriseCatalog({data:{merchantId:m.merchant_id,endpointUrl:endpoint,authType:authType as "none"|"bearer"|"api_key"|"basic",credentials:authType==="none"?undefined:authType==="basic"?(credential?{username,password:credential}:undefined):authType==="bearer"?(credential?{token:credential}:undefined):(credential?{apiKey:credential}:undefined),responsePath:existing?.response_path??"products",syncMode:(existing?.sync_mode??"upsert_only") as "upsert_only"|"snapshot",webhookEnabled,webhookSecret:webhookSecret||undefined,pageSize:Number(pageSize),cursorParam:existing?.cursor_param??"cursor",cursorPath:cursorPath||undefined,inventoryStaleAfterSeconds:Number(staleAfter),orderEndpointUrl:orderEndpoint||undefined,orderWebhookSecret:orderWebhookSecret||undefined,fieldMapping}})},"Enterprise configuration saved")}}><label className="text-sm font-bold lg:col-span-2">Catalog endpoint<input required type="url" value={endpoint} onChange={e=>setEndpoint(e.target.value)} className="mt-1 h-11 w-full rounded-xl border border-market-line px-3" placeholder="https://erp.example.com/api/products"/></label><label className="text-sm font-bold">Authentication<select value={authType} onChange={e=>{setAuthType(e.target.value);setCredential("")}} className="mt-1 h-11 w-full rounded-xl border border-market-line px-3"><option value="none">None</option><option value="bearer">Bearer</option><option value="api_key">API key</option><option value="basic">Basic</option></select></label>{authType==="basic"?<label className="text-sm font-bold">Username<input value={username} onChange={e=>setUsername(e.target.value)} className="mt-1 h-11 w-full rounded-xl border border-market-line px-3" autoComplete="username"/></label>:<div/>}<label className="text-sm font-bold lg:col-span-2">{authType==="none"?"Credential":"Credential / new credential"}<input type="password" value={credential} onChange={e=>setCredential(e.target.value)} placeholder={existing&&authType===existing.auth_type?"Leave blank to keep existing credential":"Enter new credential"} className="mt-1 h-11 w-full rounded-xl border border-market-line px-3" autoComplete="new-password"/></label><label className="flex items-center gap-2 text-sm font-bold"><input type="checkbox" checked={webhookEnabled} onChange={e=>setWebhookEnabled(e.target.checked)}/> Enable catalog webhooks</label><label className="text-sm font-bold">Webhook secret<input type="password" minLength={webhookEnabled?32:0} value={webhookSecret} onChange={e=>setWebhookSecret(e.target.value)} placeholder={webhookEnabled?"32+ characters; blank keeps existing":"Optional"} className="mt-1 h-11 w-full rounded-xl border border-market-line px-3" autoComplete="new-password"/></label><label className="text-sm font-bold">Order endpoint<input type="url" value={orderEndpoint} onChange={e=>setOrderEndpoint(e.target.value)} placeholder="Optional ERP order endpoint" className="mt-1 h-11 w-full rounded-xl border border-market-line px-3"/></label><label className="text-sm font-bold">Order HMAC secret<input type="password" minLength={orderWebhookSecret?32:0} value={orderWebhookSecret} onChange={e=>setOrderWebhookSecret(e.target.value)} placeholder="Optional; 32+ characters" className="mt-1 h-11 w-full rounded-xl border border-market-line px-3" autoComplete="new-password"/></label><label className="text-sm font-bold">Page size<input type="number" min={1} max={1000} value={pageSize} onChange={e=>setPageSize(e.target.value)} className="mt-1 h-11 w-full rounded-xl border border-market-line px-3"/></label><label className="text-sm font-bold">Cursor JSON path<input value={cursorPath} onChange={e=>setCursorPath(e.target.value)} placeholder="pagination.nextCursor" className="mt-1 h-11 w-full rounded-xl border border-market-line px-3"/></label><label className="text-sm font-bold">Inventory stale threshold (seconds)<input type="number" min={60} max={604800} value={staleAfter} onChange={e=>setStaleAfter(e.target.value)} className="mt-1 h-11 w-full rounded-xl border border-market-line px-3"/></label><label className="text-sm font-bold lg:col-span-2">Field mapping JSON<textarea value={mappingJson} onChange={e=>setMappingJson(e.target.value)} rows={8} className="mt-1 w-full rounded-xl border border-market-line p-3 font-mono text-xs"/></label><div className="flex flex-wrap gap-2 lg:col-span-2"><Button disabled={busy}>Save configuration</Button>{existing?<><Button type="button" className="bg-black text-white" disabled={busy} onClick={()=>void run(()=>testMerchantEnterpriseConnection({data:{merchantId:m.merchant_id}}),"Enterprise connection test completed")}>Test connection</Button><Button type="button" className="bg-market-soft text-market-ink" disabled={busy} onClick={()=>void run(()=>syncMerchantEnterpriseCatalog({data:{merchantId:m.merchant_id}}),"Enterprise catalog sync completed")}>Sync catalog</Button></>:null}</div></form></Card>
  <div className="grid gap-5 lg:grid-cols-2"><Card title="Connection health">{health?.connection?<div className="mt-4 space-y-3 text-sm"><Row a="Connection" b={health.connection.status}/><Row a="Webhook" b={health.connection.webhook_enabled?"Enabled":"Disabled"}/><Row a="Last sync" b={health.connection.last_sync_completed_at?date(health.connection.last_sync_completed_at):"Never"}/><Row a="Sync result" b={health.connection.last_sync_status??"Never"}/><Row a="Records in last sync" b={String(health.connection.last_sync_count??0)}/><Row a="Consecutive failures" b={String(health.connection.consecutive_sync_failures??0)}/>{health.connection.next_sync_at?<Row a="Next scheduled retry" b={date(health.connection.next_sync_at)}/>:null}<Row a="Inventory freshness" b={health.connection.last_inventory_sync_at?date(health.connection.last_inventory_sync_at):"Not synchronized"}/><Row a="Last connection test" b={health.connection.last_connection_test_at?`${health.connection.last_connection_test_status??"unknown"} · ${date(health.connection.last_connection_test_at)}`:"Never"}/>{health.connection.last_connection_test_error?<p className="rounded-lg bg-market-soft p-2 text-xs">Last test: {health.connection.last_connection_test_error}</p>:null}</div>:<p className="mt-4 text-sm text-market-muted">Enterprise integration is not configured.</p>}</Card><Card title="Operating boundary"><ul className="mt-4 space-y-2 text-sm leading-6 text-market-muted"><li>• External enterprise catalog is authoritative.</li><li>• Partial syncs do not deactivate the existing snapshot.</li><li>• Webhooks are signature-verified, deduplicated and retried.</li><li>• Enterprise order delivery is asynchronous and idempotent.</li><li>• Payment settlement/refunds remain with the configured provider.</li></ul></Card></div>
  <div className="grid gap-5 lg:grid-cols-3"><Card title="Recent sync runs"><div className="space-y-3">{ops?.syncRuns.map((x:EnterpriseSyncRun)=><div key={String(x.id)} className="border-b border-market-line pb-3"><div className="flex justify-between gap-3"><b>{String(x.status)}</b><span className="text-xs text-market-muted">{x.started_at?date(String(x.started_at)):""}</span></div><p className="text-xs text-market-muted">{String(x.source)} · {String(x.upserted_count??0)} upserted · {String(x.error_count??0)} errors</p></div>)}{!ops?.syncRuns.length?<p className="text-sm text-market-muted">No sync runs recorded.</p>:null}</div></Card><Card title="Webhook queue"><div className="space-y-3">{ops?.webhookEvents.map((x:EnterpriseWebhookEvent)=><div key={String(x.id)} className="border-b border-market-line pb-3"><div className="flex justify-between gap-3"><b>{String(x.event_type)}</b><span className="text-xs font-bold">{String(x.status)}</span></div><p className="text-xs text-market-muted">Attempts: {String(x.attempts??0)} · {x.received_at?date(String(x.received_at)):""}</p>{x.error_code?<p className="mt-1 text-xs">{String(x.error_code).replaceAll("_"," ")}</p>:null}</div>)}{!ops?.webhookEvents.length?<p className="text-sm text-market-muted">No webhook events recorded.</p>:null}</div></Card><Card title="Order delivery queue"><div className="space-y-3">{ops?.orderOutbox.map((x:EnterpriseOrderOutbox)=><div key={String(x.id)} className="border-b border-market-line pb-3"><div className="flex justify-between gap-3"><b>{String(x.event_type)}</b><span className="text-xs font-bold">{String(x.status)}</span></div><p className="text-xs text-market-muted">Order {String(x.order_id)} · Attempts {String(x.attempts??0)}</p>{x.error_code?<p className="mt-1 text-xs">{String(x.error_code).replaceAll("_"," ")}</p>:null}</div>)}{!ops?.orderOutbox.length?<p className="text-sm text-market-muted">No enterprise order events recorded.</p>:null}</div></Card></div>
 </div>
}
